const trigger = $('استقبال رسالة واتساب').item.json;
const msg = trigger.messages ? trigger.messages[0] : null;

// تجاهل الأحداث اللي مش رسائل (تحديثات حالة: تم الإرسال/التسليم/القراءة)
if (!msg) {
  return [];
}

const phone = msg.from;
const tail = String(phone).replace(/\D/g, '').slice(-10);

// فحص المحظورين: هل رقم المرسِل موجود في أي خانة في شيت المحظورين؟
const blockedRows = $('فحص المحظورين').all();
const blocked = blockedRows.some(r =>
  Object.values(r.json).some(v => {
    const d = String(v).replace(/\D/g, '');
    return d.length >= 10 && d.slice(-10) === tail;
  })
);

const customerRows = $('فحص العميل').all().filter(r => Object.keys(r.json).length > 0);
const existing = customerRows.length > 0 ? customerRows[0].json : null;
const status = existing ? existing.Status : null;

let route;
if (blocked || status === 'closed_no_transfer' || status === 'closed_transfer') {
  route = 'stop';
} else if (!existing && msg.type === 'text') {
  route = 'welcome';
} else {
  route = 'agent';
}

let agent_input;
if (msg.type === 'interactive') {
  const id = msg.interactive.button_reply.id;
  if (id === 'inquiry') agent_input = 'العميل دوس على زرار: عندي استفسار. ابدأ تجمع بياناته.';
  else if (id === 'transfer_yes') agent_input = 'العميل دوس على زرار: تحويل لخدمة العملاء. حوله دلوقتي.';
  else if (id === 'transfer_no') agent_input = 'العميل دوس على زرار: لا شكرًا. سجل بياناته واقفل من غير تحويل.';
  else agent_input = id;
} else {
  agent_input = msg.text?.body || '';
}

return [{ json: { phone, route, agent_input } }];

